// Guide titles and summaries for code that runs outside Astro's content layer (llms.txt is
// generated by a Vite script). Reads the Markdown frontmatter directly, so it cannot drift.
const files = import.meta.glob<string>('../content/guides/*.md', { eager: true, query: '?raw', import: 'default' });

/** Reads a top-level `key: 'value'` (or bare value) line from simple YAML frontmatter. */
const field = (src: string, key: string) => {
  const m = src.match(new RegExp(`^${key}:\\s*(.+)$`, 'm'));
  if (!m) throw new Error(`Guide frontmatter is missing "${key}"`);
  return m[1].trim().replace(/^'(.*)'$/, '$1').replace(/''/g, "'");
};

export const GUIDE_INDEX = Object.entries(files)
  .map(([path, src]) => ({
    slug: path.split('/').pop()!.replace(/\.md$/, ''),
    h1: field(src, 'h1'),
    summary: field(src, 'summary'),
    order: Number(field(src, 'order')),
  }))
  .sort((a, b) => a.order - b.order);
